    a=[r[:] for r in grid]
    H,W=len(a),len(a[0])
    # infer compartment centers from divider rows/columns (lines of a uniform nonzero color)
    dr=[i for i,row in enumerate(a) if len(set(row))==1 and row[0]!=0]
    dc=[j for j in range(W) if len({a[i][j] for i in range(H)})==1 and a[0][j]!=0]
    rs=[]; last=-1
    for x in dr+[H]:
        if x>last+1: rs.append((last+1,x-1))
        last=x
    cs=[]; last=-1
    for x in dc+[W]:
        if x>last+1: cs.append((last+1,x-1))
        last=x
    # block colors
    counts={}; blocks={}
    for ri,(r0,r1) in enumerate(rs):
      for ci,(c0,c1) in enumerate(cs):
        vals=[a[r][c] for r in range(r0,r1+1) for c in range(c0,c1+1)]
        v=max(set(vals),key=vals.count)
        if v!=0: counts[v]=counts.get(v,0)+1; blocks.setdefault(v,[]).append((ri,ci))
    if not counts:return a
    # connector is color with greatest number of colored blocks; other colored block is anchor/decoration
    col=max(counts,key=counts.get); pts=blocks[col]
    if len(pts)<2:return a
    # connect pairs sharing row/column; then use L paths between successive points
    edges=[]
    for p in pts[1:]:
      q=min(pts[:pts.index(p)] or [pts[0]],key=lambda z:abs(z[0]-p[0])+abs(z[1]-p[1]))
      edges.append((q,p))
    for (r1,c1),(r2,c2) in edges:
      # horizontal then vertical
      for c in range(min(c1,c2),max(c1,c2)+1):
       for r in range(min(r1,r2),max(r1,r2)+1):
        if (r==r1 and c>=min(c1,c2) and c<=max(c1,c2)) or (c==c2 and r>=min(r1,r2) and r<=max(r1,r2)):
         for rr in range(rs[r][0],rs[r][1]+1):
          for cc in range(cs[c][0],cs[c][1]+1):
           if a[rr][cc]==0:a[rr][cc]=col
    return a"}

